  estimated_duration = '10–12 days',
  phases = '[{"id":"phase-1","title":"Phase 1: Preparation & Conditioning","description":"Permits, gear acquisition, and high-altitude training","target_date":"2027-08-15","tasks":[{"id":"task-1-1","title":"Obtain ACAP & TIMS permits in Pokhara","description":"Submit paperwork and passport photos at the Nepal Tourism Board in Damside, Pokhara","deadline":"2027-08-15","completed":true,"subtasks":[{"id":"sub-1-1-1","title":"4 passport-size photographs","completed":true},{"id":"sub-1-1-2","title":"Insurance policy covering helicopter rescue up to 5,000m","completed":true}]},{"id":"task-1-2","title":"Gear check: thermal layers, microspikes & trekking poles","description":"Inspect cold-weather layers and break in waterproof trekking boots on practice trails","deadline":"2027-09-01","completed":true,"subtasks":[{"id":"sub-1-2-1","title":"Break in trekking boots on 15km weekend hikes","completed":true},{"id":"sub-1-2-2","title":"Purchase Merino wool thermal base layers & UV sunglasses","completed":true}]}]},{"id":"phase-2","title":"Phase 2: Travel & Foothill Trekking","description":"Journey from Pokhara to the Modi Khola trailhead and climb to Chhomrong","target_date":"2027-10-08","tasks":[{"id":"task-2-1","title":"Fly to Kathmandu and scenic drive to Pokhara","description":"Arrive in Kathmandu (KTM) and take coach or flight to lakeside Pokhara","deadline":"2027-10-05","completed":false,"subtasks":[{"id":"sub-2-1-1","title":"Exchange cash for Nepalese Rupees (NPR) for trail teahouses","completed":false},{"id":"sub-2-1-2","title":"Purchase local NTC / Ncell SIM card for connectivity","completed":false}]},{"id":"task-2-2","title":"Trek Days 1–3: Nayapul to Ghandruk and Chhomrong","description":"Ascend stone staircases through Gurung villages with views of Annapurna South","deadline":"2027-10-08","completed":false,"subtasks":[{"id":"sub-2-2-1","title":"Reach Ghandruk village (1,940m)","completed":false},{"id":"sub-2-2-2","title":"Cross Chhomrong Khola suspension bridge to upper Chhomrong (2,170m)","completed":false}]}]},{"id":"phase-3","title":"Phase 3: Deep Sanctuary & Summit","description":"Enter the alpine gorge beneath Machapuchare and reach the ABC amphitheater","target_date":"2027-10-14","tasks":[{"id":"task-3-1","title":"Trek Days 4–6: Bamboo through Deurali to MBC (3,700m)","description":"Hike along Modi Khola gorge, acclimatizing steadily into sub-alpine terrain","deadline":"2027-10-12","completed":false,"subtasks":[{"id":"sub-3-1-1","title":"Acclimatize at Deurali (3,200m) with plenty of fluids","completed":false},{"id":"sub-3-1-2","title":"Reach Machapuchare Base Camp (3,700m) before sunset","completed":false}]},{"id":"task-3-2","title":"Trek Day 7: Sunrise hike to Annapurna Base Camp (4,130m)","description":"Pre-dawn 2-hour gentle ascent into the 360-degree mountain amphitheater of Annapurna I, Annapurna South, and Hiunchuli","deadline":"2027-10-14","completed":false,"subtasks":[{"id":"sub-3-2-1","title":"Watch sunrise alpenglow illuminate the south face of Annapurna I","completed":false},{"id":"sub-3-2-2","title":"Hot ginger-lemon tea celebration at ABC lodge","completed":false}]}]},{"id":"phase-4","title":"Phase 4: Descent & Hot Springs Recovery","description":"Retrace the trail down the valley and soak in natural thermal waters","target_date":"2027-10-17","tasks":[{"id":"task-4-1","title":"Descend via Bamboo to Jhinu Danda natural hot springs","description":"Long descent down the valley, soothing tired muscles in natural riverside thermal pools","deadline":"2027-10-16","completed":false,"subtasks":[{"id":"sub-4-1-1","title":"Descend 2,000m to Jhinu Danda hot pools","completed":false},{"id":"sub-4-1-2","title":"Celebrate successful summit with team in Pokhara","completed":false}]}]}]'
